def make_entry(row):
    key, en, fa, category, level, definition, example, uses, limitation = row.split("|", 8)
    title, publisher, url = SOURCES[category]
    return {
        "key": key,
        "term": en,
        "title": fa,
        "category": category,
        "difficulty_level": level,
        "alternative_translations": [],
        "abbreviation": "",
        "short_definition": definition,
        "full_definition": f"{definition} در کاربرد عملی، باید دامنهٔ مسئله، دادهٔ مورد استفاده و معیار موفقیت آن به‌صورت جداگانه مشخص شود تا این اصطلاح با مفاهیم نزدیک اشتباه نشود.",
        "beginner_explanation": f"به زبان ساده، {definition[0].lower() + definition[1:]}",
        "technical_explanation": f"از نظر فنی، {definition[0].lower() + definition[1:]} ارزیابی آن باید با داده و معیار متناسب با دامنه انجام شود.",
        "advanced_explanation": "",
        "how_it_works": f"در یک سناریوی نمونه، ابتدا ورودی و فرض‌های مسئله مشخص می‌شوند؛ سپس این مفهوم در فرایند مربوط به کار گرفته و نتیجه با معیار مناسب بررسی می‌شود. مثال کاربردی: {example}",
        "practical_example": example,
        "code_example": "",
        "use_cases": [item.strip() for item in uses.split("؛") if item.strip()],
        "advantages": ["ایجاد چارچوب روشن برای طراحی، آموزش یا ارزیابی"],
        "limitations": [limitation],
        "source": {"title": title, "publisher": publisher, "url": url},
        "reviewed_at": None,
    }

rows = [line.strip() for line in ROWS.splitlines() if line.strip()]
entries = [make_entry(row) for row in rows]
legacy = json.loads(LEGACY.read_text(encoding="utf-8"))
old = {entry["key"] for entry in legacy["entries"]}
keys = [entry["key"] for entry in entries]
if len(entries) != 150:
    raise SystemExit(f"expected 150 entries, got {len(entries)}")
if len(set(keys)) != len(keys):
    raise SystemExit("duplicate keys in initial glossary")
overlap = sorted(old.intersection(keys))
if overlap:
    raise SystemExit("overlap with published glossary: " + ", ".join(overlap))
OUT.write_text(json.dumps({"generated_at": "2026-10-18", "status": "draft", "entries": entries}, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"wrote {len(entries)} draft entries to {OUT.relative_to(ROOT)}")
